update public.questions set body_hi = 'सम्राट अशोक के अभिलेखों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 गलत है: अधिकांश अशोक-अभिलेखों में ब्राह्मी लिपि है, पर सब में नहीं; उत्तर-पश्चिम क्षेत्र (शाहबाज़गढ़ी और मानसेहरा) के अभिलेख खरोष्ठी में हैं, और कंधार का अभिलेख यूनानी और अरामाइक में है। कथन 2 सही है: 1958 में वर्तमान अफ़ग़ानिस्तान में मिला कंधार द्विभाषी शिलालेख यूनानी और अरामाइक में है, जो मौर्य साम्राज्य की उत्तर-पश्चिमी सीमा की यूनानी और फ़ारसी-प्रभावित आबादी को दर्शाता है। कथन 3 सही है: शाहबाज़गढ़ी और मानसेहरा के अभिलेख खरोष्ठी में हैं, जो उस समय उत्तर-पश्चिमी उपमहाद्वीप में प्रचलित दाएँ से बाएँ लिखी जाने वाली लिपि थी।', updated_at = now(), question_data = question_data || '{"statements_hi": ["पूरे भारतीय उपमहाद्वीप में मिले अशोक के शिलालेख और स्तंभलेख एक समान रूप से ब्राह्मी लिपि में लिखे गए हैं।", "अशोक का कंधार द्विभाषी शिलालेख यूनानी और अरामाइक भाषाओं में है।", "उपमहाद्वीप के उत्तर-पश्चिमी भाग में शाहबाज़गढ़ी और मानसेहरा में मिले अशोक के अभिलेख खरोष्ठी लिपि में हैं।"]}'::jsonb where id = '0a32d588-7db1-47ce-a06d-ceb5bbae2cf4' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'मोहनजोदड़ो में खोजे गए विशाल स्नानागार (Great Bath) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 सही है: विशाल स्नानागार पकी हुई उत्तम ईंटों से बना है, जिसे ईंटों की दो परतों के बीच प्राकृतिक बिटुमेन (डामर) की परत लगाकर जलरोधी बनाया गया। कथन 2 सही है: इसकी सावधानीपूर्ण बनावट, दुर्ग के भीतर केंद्रीय स्थिति और घरेलू उपयोग के प्रमाण न होने के कारण पुरातत्वविद इसे अधिकतर अनुष्ठानिक या धार्मिक स्नान के कुंड के रूप में देखते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह पकी हुई ईंटों से बना है, जिन्हें प्राकृतिक बिटुमेन की परत से जलरोधी बनाया गया था।", "पुरातत्वविद इसे सबसे अधिक अनुष्ठानिक या धार्मिक स्नान के लिए प्रयुक्त संरचना मानते हैं।"]}'::jsonb where id = '1e38d678-cf3d-49ab-957b-58165c6a10fb' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'संगम युग के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। संगम साहित्य आरंभिक ईसवी शताब्दियों के तमिल समाज और राजव्यवस्था को दर्शाता है। व्याकरण और काव्यशास्त्र का ग्रंथ तोलकाप्पियम सबसे आरंभिक संगम रचनाओं में गिना जाता है। संगम राजव्यवस्था पर तीन शासक घरानों, चोल, चेर और पांड्य, का प्रभुत्व था।', updated_at = now(), question_data = question_data || '{"statements_hi": ["संगम साहित्य मुख्य रूप से ईसवी सन् की आरंभिक शताब्दियों में तमिल क्षेत्र के सामाजिक, आर्थिक और राजनीतिक जीवन का वर्णन करता है।", "तमिल व्याकरण और काव्यशास्त्र का ग्रंथ ''तोलकाप्पियम'' सबसे आरंभिक संगम ग्रंथों में से एक माना जाता है।", "संगम युग के तीन प्रमुख शासक राजवंश चोल, चेर और पांड्य थे।"]}'::jsonb where id = '966747db-37e0-41e8-ba49-c3834c11c01e' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'अजंता और एलोरा की शैलकृत गुफाओं के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। अजंता की गुफाएँ पूरी तरह बौद्ध हैं, जिनमें चैत्य और विहार, दोनों हैं। इसके विपरीत, एलोरा में बौद्ध, हिंदू और जैन गुफाएँ साथ-साथ हैं। एलोरा का एकाश्म (monolithic) कैलास मंदिर, जो ऊपर से नीचे की ओर काटा गया और शिव को समर्पित है, राष्ट्रकूट शासक कृष्ण प्रथम के समय बनवाया गया।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अजंता की गुफाएँ मुख्य रूप से बौद्ध हैं, जिनमें चैत्य (प्रार्थना-कक्ष) और विहार (मठ), दोनों हैं।", "अजंता के विपरीत, एलोरा की गुफाओं में तीन धर्मों, बौद्ध, हिंदू और जैन, की शैलकृत संरचनाएँ हैं।", "एक ही चट्टान को ऊपर से नीचे की ओर काटकर बनाया गया और शिव को समर्पित एलोरा का कैलास मंदिर राष्ट्रकूट शासक कृष्ण प्रथम के संरक्षण में बना।"]}'::jsonb where id = 'cf1cd154-944c-47c0-b7bf-186d712216df' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'हर्षवर्धन के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 3 सही है: हर्ष के दक्षिण की ओर विस्तार को चालुक्य शासक पुलकेशिन द्वितीय ने नर्मदा पर रोक दिया। कथन 1 गलत यात्री का नाम देता है: हर्ष के दरबार में ह्वेनसांग आया था; फाह्यान लगभग दो सौ वर्ष पहले चंद्रगुप्त द्वितीय के समय भारत आया था। कथन 2 गलत है: हर्षचरित दरबारी कवि बाणभट्ट ने लिखा, हर्ष ने नहीं; हर्ष को रत्नावली, प्रियदर्शिका और नागानंद जैसे नाटकों का श्रेय दिया जाता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["हर्षवर्धन के दरबार में चीनी यात्री फाह्यान आया था।", "हर्ष की जीवनी ''हर्षचरित'' स्वयं हर्ष ने लिखी थी।", "नर्मदा नदी के तट पर चालुक्य शासक पुलकेशिन द्वितीय ने हर्ष को निर्णायक रूप से पराजित किया।"]}'::jsonb where id = 'd6291cea-17d1-42ae-b885-a3767577c2fb' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'सिंधु घाटी सभ्यता में व्यापार के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। लोथल में एक गोदीबाड़ा (dockyard) था, जो समुद्री व्यापार का प्रमाण है। मेसोपोटामिया के ग्रंथ ''मेलुहा'' नामक एक व्यापारिक क्षेत्र का उल्लेख करते हैं, जिसे व्यापक रूप से सिंधु क्षेत्र माना जाता है। हड़प्पा के बाट छोटी इकाइयों के लिए मोटे तौर पर मानकीकृत, लगभग द्विआधारी (binary) क्रम (1, 2, 4, 8, 16...) पर चलते थे।', updated_at = now(), question_data = question_data || '{"statements_hi": ["वर्तमान गुजरात में स्थित लोथल में एक गोदीबाड़ा था, जो समुद्री व्यापार का संकेत देता है।", "हड़प्पावासियों के मेसोपोटामिया के साथ व्यापारिक संबंध थे, और मेसोपोटामिया के ग्रंथ उन्हें ''मेलुहा'' कहते हैं।", "हड़प्पावासी बाटों की एक मानकीकृत प्रणाली का उपयोग करते थे, जो छोटी इकाइयों के लिए मोटे तौर पर द्विआधारी क्रम पर चलती थी।"]}'::jsonb where id = '29f57355-b83d-4544-8d0c-6f156196ef2e' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'गुप्त प्रशासन के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 सही है: गुप्त शासक महाराजाधिराज और परम भट्टारक जैसी उपाधियाँ धारण करते थे। कथन 2 सही है: ब्राह्मणों को प्रायः कर-मुक्त भूमि-दान (अग्रहार) गुप्तकालीन ताम्रपत्र अभिलेखों में भली-भाँति प्रमाणित हैं। कथन 3 गलत है और वास्तविक तुलना को उलट देता है: गुप्त प्रशासन को आम तौर पर मौर्य प्रशासन से कम केंद्रीकृत माना जाता है, जिसमें प्रांतीय और स्थानीय अधिकारियों को अधिक स्वायत्तता थी; कुछ इतिहासकार इसे भारतीय सामंतवाद की शुरुआत का आरंभिक संकेत मानते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["गुप्त शासक सर्वोच्च संप्रभुता दर्शाने के लिए ''महाराजाधिराज'' और ''परम भट्टारक'' जैसी उपाधियाँ धारण करते थे।", "ब्राह्मणों और धार्मिक संस्थाओं को प्रायः कर-मुक्त भूमि-दान गुप्त काल में एक आम प्रथा बन गई, जिसका प्रमाण ताम्रपत्र अभिलेख हैं।", "गुप्त प्रशासन मौर्य प्रशासन से अधिक केंद्रीकृत था, जिसमें प्रांतीय और स्थानीय शासकों को कम स्वायत्तता थी।"]}'::jsonb where id = '84e4d0b5-1d9b-4480-9fe0-a0cb0addd440' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'बौद्ध संगीतियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 सही है: पहली संगीति बुद्ध के परिनिर्वाण के तुरंत बाद राजगृह में हुई। कथन 2 सही है: वैशाली की दूसरी संगीति में मठीय अनुशासन के प्रश्नों पर स्थविरवादियों और महासांघिकों में विभाजन हुआ। कथन 3 गलत है: परंपरा के अनुसार कनिष्क के समय की चौथी संगीति कश्मीर के कुंडलवन में हुई, पाटलिपुत्र में नहीं; पाटलिपुत्र अशोक के समय हुई तीसरी संगीति का स्थल था।', updated_at = now(), question_data = question_data || '{"statements_hi": ["पहली बौद्ध संगीति बुद्ध की मृत्यु के तुरंत बाद राजगृह में हुई।", "वैशाली में हुई दूसरी बौद्ध संगीति के कारण स्थविरवादियों और महासांघिकों के बीच विभाजन हुआ।", "कनिष्क के संरक्षण में हुई चौथी बौद्ध संगीति पाटलिपुत्र में हुई।"]}'::jsonb where id = '6b4a08ee-d23b-4b8c-88b0-72aa7f734b17' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'महाजनपदों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 सही है: मगध की राजधानी राजगृह से पाटलिपुत्र (उदायिन के समय) ले जाई गई। कथन 2 सही है: अवंति, मगध, कोसल और वत्स को प्रायः उस काल की चार प्रमुख शक्तियाँ माना जाता है। कथन 3 गलत है: वज्जि (वृज्जि संघ, राजधानी वैशाली) गण-संघ, यानी गणतांत्रिक/कुलीनतंत्रीय संघ, का मानक उदाहरण है, मगध जैसा वंशानुगत राजतंत्र नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["मगध की राजधानी पहले राजगृह थी, जिसे बाद में पाटलिपुत्र ले जाया गया।", "उज्जयिनी राजधानी वाला अवंति, मगध, कोसल और वत्स के साथ चार प्रमुख राजतंत्रीय महाजनपदों में से एक था।", "वज्जि एक ऐसा महाजनपद था जो मगध की तरह वंशानुगत राजा के अधीन राजतंत्र के रूप में संगठित था।"]}'::jsonb where id = 'd94e4ec9-dd4c-4651-9fdd-65d664d98c82' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'जैन धर्म के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 सही है: महावीर का जन्म वैशाली के पास कुंडग्राम में हुआ। कथन 2 गलत है: परंपरा के अनुसार 12 अंगों का संकलन पाटलिपुत्र की जैन संगीति (स्थूलभद्र के अधीन) से जुड़ा है, वैशाली से नहीं; वैशाली का जैन धर्म से संबंध मुख्य रूप से महावीर के जन्मस्थान के रूप में है (और, अलग से, दूसरी बौद्ध संगीति के स्थल के रूप में)। कथन 3 सही है: जैन परंपरा श्वेतांबर-दिगंबर विभाजन को चंद्रगुप्त मौर्य के शासनकाल के 12 वर्ष के अकाल से जोड़ती है, जब भद्रबाहु एक दल को दक्षिण ले गए और स्थूलभद्र मगध में रहे।', updated_at = now(), question_data = question_data || '{"statements_hi": ["24वें तीर्थंकर महावीर का जन्म वैशाली के पास कुंडग्राम में हुआ।", "वैशाली में हुई जैन संगीति से 12 अंगों का संकलन हुआ।", "जैन धर्म के श्वेतांबर और दिगंबर संप्रदायों का विभाजन परंपरागत रूप से चंद्रगुप्त मौर्य के शासनकाल में पड़े एक अकाल से जोड़ा जाता है।"]}'::jsonb where id = 'e7460676-e846-4810-aaa4-316e503a39d7' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारतीय राष्ट्रीय पंचांग में ग्रेगोरियन कैलेंडर के साथ प्रयुक्त शक संवत् परंपरागत रूप से 78 ई. से माना जाता है और किस शासक के राज्यारोहण से जुड़ा है?', explanation_hi = '78 ई. का शक संवत् परंपरागत रूप से कुषाण शासक कनिष्क के राज्यारोहण से जोड़ा जाता है, यद्यपि संवत् का नाम शक मूल का संकेत देता है। पश्चिमी क्षत्रप (शक) शासक रुद्रदामन प्रथम संवत् के नाम के कारण ही आकर्षक गलत विकल्प है, पर उन्हें इसकी शुरुआत का श्रेय नहीं दिया जाता। चंद्रगुप्त द्वितीय और कडफ़िसेस प्रथम अलग राजवंशों और कालों के हैं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "कनिष्क", "b": "चंद्रगुप्त द्वितीय", "c": "कडफ़िसेस प्रथम", "d": "रुद्रदामन प्रथम"}'::jsonb as hi) h) where id = '303521c0-2584-4d39-8838-f5d82f08193f' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'दूसरे मौर्य सम्राट और अशोक के पिता बिंदुसार को यूनानी विवरणों में किस उपाधि/नाम से पुकारा गया है?', explanation_hi = 'यूनानी लेखकों ने बिंदुसार को ''अमित्रोकेटस'' कहा (जो ''अमित्रघात'', यानी मोटे तौर पर ''शत्रुओं का संहारक'', का यूनानी रूप है)। ''सैंड्रोकोट्टस'' बिंदुसार के पिता चंद्रगुप्त मौर्य का यूनानी नाम है, स्वयं बिंदुसार का नहीं। ''देवानंपिय'' और ''पियदसि'' अशोक के अभिलेखों में उनसे जुड़े विशेषण हैं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "सैंड्रोकोट्टस", "b": "अमित्रोकेटस", "c": "देवानंपिय", "d": "पियदसि"}'::jsonb as hi) h) where id = '5b146f53-96e1-4fc4-8898-6ebad1ad06a1' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'गौतमी बलश्री के नासिक प्रशस्ति अभिलेख के अनुसार, सातवाहन वंश के उनके पुत्र गौतमीपुत्र सातकर्णि ने किस शक शासक को पराजित किया?', explanation_hi = 'नासिक प्रशस्ति में गौतमीपुत्र सातकर्णि द्वारा पश्चिमी क्षत्रप (शक) शासक नहपान की पराजय दर्ज है। रुद्रदामन प्रथम एक संबंधित पर अलग व्यक्ति है; उसने बाद में उलटे सातवाहनों को हराया, इसीलिए यहाँ उसे लेकर भ्रम होता है। मिनांडर पहले का एक हिंद-यूनानी राजा था, और कनिष्क कुषाण शासक, जिनका इस घटना से कोई संबंध नहीं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "रुद्रदामन प्रथम", "b": "मिनांडर", "c": "कनिष्क", "d": "नहपान"}'::jsonb as hi) h) where id = 'a880878f-aa89-4112-8266-c185f5bcbb27' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'प्राचीन शिक्षा के प्रमुख केंद्र नालंदा विश्वविद्यालय की स्थापना का श्रेय परंपरागत रूप से किस गुप्त शासक के संरक्षण को दिया जाता है?', explanation_hi = 'परंपरा के अनुसार नालंदा की स्थापना का श्रेय पाँचवीं शताब्दी ई. के आरंभ में कुमारगुप्त प्रथम को दिया जाता है। समुद्रगुप्त और चंद्रगुप्त द्वितीय उससे पहले हुए और क्रमशः सैनिक विस्तार तथा ''विक्रमादित्य'' उपाधि से जुड़े हैं, जबकि स्कंदगुप्त मुख्य रूप से हूण आक्रमणों को रोकने के लिए याद किया जाता है; इनमें से किसी को नालंदा की स्थापना का श्रेय नहीं दिया जाता।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "समुद्रगुप्त", "b": "चंद्रगुप्त द्वितीय", "c": "कुमारगुप्त प्रथम", "d": "स्कंदगुप्त"}'::jsonb as hi) h) where id = '9ad1eba4-1800-4738-a3fd-51a78060d63c' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'कण्णगी के चरित्र पर केंद्रित संगम-कालीन तमिल महाकाव्य ''शिलप्पदिकारम'' किसकी रचना माना जाता है?', explanation_hi = 'शिलप्पदिकारम इलंगो अडिगल की रचना मानी जाती है। सात्तनार को परंपरागत रूप से ''मणिमेकलै'' का लेखक माना जाता है, जो कण्णगी की पुत्री की कथा आगे बढ़ाने वाला सहयोगी महाकाव्य है; दोनों रचनाओं के विषय-संबंध के कारण यहाँ भ्रम होता है। तिरुवल्लुवर अलग नैतिक ग्रंथ ''तिरुक्कुरल'' से जुड़े हैं, और नक्कीरर संगम काल के एक अन्य कवि हैं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "सात्तनार", "b": "तिरुवल्लुवर", "c": "इलंगो अडिगल", "d": "नक्कीरर"}'::jsonb as hi) h) where id = '5157d7ac-75f0-4f9a-83aa-4d3994937e46' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'यूनानी राजदूत मेगस्थनीज़, जिसका विवरण ''इंडिका'' मौर्य भारत के बारे में बहुमूल्य जानकारी देता है, किस हेलेनिस्टिक शासक द्वारा चंद्रगुप्त मौर्य के दरबार में भेजा गया था?', explanation_hi = 'दोनों शासकों के बीच संधि के बाद सिकंदर के उत्तराधिकारियों में से एक, सेल्यूकस प्रथम निकेटर, ने मेगस्थनीज़ को चंद्रगुप्त मौर्य के दरबार में राजदूत बनाकर भेजा। सिकंदर महान की इस दूत-मंडल से पहले ही (323 ई.पू.) मृत्यु हो चुकी थी, पर भारत-यूनानी संपर्क के इस काल से उसके सामान्य संबंध के कारण वह आकर्षक गलत उत्तर है। एंटियोकस प्रथम और टॉलेमी प्रथम सेल्यूकस के समकालीन थे, पर उन्होंने मेगस्थनीज़ को नहीं भेजा।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "सिकंदर महान", "b": "एंटियोकस प्रथम", "c": "टॉलेमी प्रथम", "d": "सेल्यूकस प्रथम निकेटर"}'::jsonb as hi) h) where id = '2457898e-0b94-4e55-b02d-b8da5c7d46fd' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'हरिषेण द्वारा रचित प्रयाग प्रशस्ति (स्तंभ-लेख) किस गुप्त शासक के शासन और सैनिक अभियानों का प्रमुख स्रोत है?', explanation_hi = 'दरबारी कवि हरिषेण द्वारा रचित प्रयाग प्रशस्ति समुद्रगुप्त के सैनिक अभियानों की प्रशंसा करती है और उसकी विजयों के विस्तार को समझने का प्रमुख स्रोत है। चंद्रगुप्त प्रथम समुद्रगुप्त के पिता और पूर्ववर्ती थे; चंद्रगुप्त द्वितीय और कुमारगुप्त प्रथम बाद के गुप्त शासक थे, जिनके शासन अलग अभिलेखों से ज्ञात होते हैं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "चंद्रगुप्त प्रथम", "b": "समुद्रगुप्त", "c": "चंद्रगुप्त द्वितीय", "d": "कुमारगुप्त प्रथम"}'::jsonb as hi) h) where id = '07500f01-6631-4dde-809c-0592c9595c09' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'प्राचीन कलिंग के राजनीतिक इतिहास का महत्त्वपूर्ण स्रोत हाथीगुंफा अभिलेख किस शासक ने जारी किया?', explanation_hi = 'भुवनेश्वर के पास मिला हाथीगुंफा अभिलेख कलिंग के चेदि/महामेघवाहन शासक खारवेल ने जारी किया, और इसमें उसके शासन और सैनिक अभियानों का विवरण है। रुद्रदामन प्रथम का ऐसा ही अभिलेख जूनागढ़ शिलालेख है; कलिंग से जुड़े अशोक के अभिलेख (पृथक कलिंग शिलालेख) खारवेल से पहले के एक अलग काल के हैं; और गौतमीपुत्र सातकर्णि नासिक प्रशस्ति से जुड़े हैं, जिसका कलिंग से संबंध नहीं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "खारवेल", "b": "रुद्रदामन प्रथम", "c": "अशोक", "d": "गौतमीपुत्र सातकर्णि"}'::jsonb as hi) h) where id = 'c277664d-877e-4835-9645-02bf8bae4917' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'जूनागढ़ शिलालेख, जो लंबाई की दृष्टि से संस्कृत के सबसे आरंभिक ज्ञात अभिलेखों में से एक है, किस शासक ने जारी किया और यह किस संरचना की मरम्मत के उल्लेख के लिए प्रसिद्ध है?', explanation_hi = 'जूनागढ़ शिलालेख पश्चिमी क्षत्रप (शक) शासक रुद्रदामन प्रथम ने जारी किया, और इसमें मौर्यों के समय बनी सुदर्शन झील की उसके द्वारा मरम्मत दर्ज है। अशोक के शिलालेख एक अलग अभिलेख-समूह हैं, जो इस अभिलेख की परिष्कृत संस्कृत के बजाय अधिकतर प्राकृत में हैं; समुद्रगुप्त प्रयाग प्रशस्ति से जुड़ा है और महरौली लौह स्तंभ का अभिलेख एक ''चंद्र'' से जुड़ा है (जिसे परंपरागत रूप से चंद्रगुप्त द्वितीय माना जाता है); और खारवेल का हाथीगुंफा अभिलेख कलिंग से जुड़ा एक अलग अभिलेख है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "रुद्रदामन प्रथम; सुदर्शन झील", "b": "अशोक; बराबर गुफाएँ", "c": "समुद्रगुप्त; महरौली लौह स्तंभ", "d": "खारवेल; हाथीगुंफा गुफाएँ"}'::jsonb as hi) h) where id = '0dfb8f7c-0d6a-4c81-ac66-091f67c23ed9' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारतीय-इस्लामी स्थापत्य के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। भारतीय-इस्लामी स्थापत्य ने देशी शहतीरी (trabeate) परंपरा को तुर्कों द्वारा लाई गई मेहराबी (arcuate) परंपरा से मिलाया; अलाई दरवाज़ा दिल्ली सल्तनत के स्थापत्य में वैज्ञानिक ढंग से बनाए गए असली मेहराब और गुंबद के आरंभिक उदाहरण के रूप में व्यापक रूप से माना जाता है; और कुतुब परिसर की पहले की संरचनाओं में टोड़ेदार (corbelling) तकनीक का प्रयोग जारी रहा, जो अचानक बदलाव के बजाय धीरे-धीरे, समन्वयवादी संक्रमण दर्शाता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["भारतीय-इस्लामी स्थापत्य देशी शहतीरी (खंभा-और-धरन) परंपरा और तुर्कों द्वारा लाई गई मेहराबी (असली मेहराब-और-गुंबद) परंपरा का संश्लेषण है।", "अलाउद्दीन खिलजी के समय बने अलाई दरवाज़े को दिल्ली सल्तनत स्थापत्य की उन सबसे आरंभिक संरचनाओं में माना जाता है जिनमें वैज्ञानिक ढंग से बना असली मेहराब और गुंबद प्रयुक्त हुआ।", "दिल्ली सल्तनत की आरंभिक संरचनाएँ, जैसे कुतुब परिसर के कुछ भाग, शुरू में असली मेहराब के बजाय टोड़ेदार तकनीक पर निर्भर थीं, जो तुर्की शासन आने के बाद भी देशी निर्माण-पद्धतियों पर निर्भरता दर्शाता है।"]}'::jsonb where id = '8fc2bdc0-b076-4c04-ac00-ebe7026d04cb' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'बौद्ध स्तूप स्थापत्य में गुंबद के शीर्ष पर अस्थि-कक्ष को घेरने वाली चौकोर रेलिंग क्या कहलाती है?', explanation_hi = '''हर्मिका'' स्तूप के गुंबद के ऊपर की चौकोर रेलिंग है, जो अस्थि-कक्ष को घेरती है और ऊपर के छत्र को सहारा देती है। ''अंड'' स्वयं अर्धगोलाकार गुंबद है; ''छत्र'' संरचना के शीर्ष पर छतरी के आकार का शिखर है; और ''वेदिका'' स्तूप के आधार को घेरने वाली रेलिंग है; हर एक अलग संरचनात्मक अंग है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "हर्मिका", "b": "अंड", "c": "छत्र", "d": "वेदिका"}'::jsonb as hi) h) where id = '6a87af1a-461c-495e-88ba-4b11aa78c893' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'मंदिरों और उन राजवंशों के निम्नलिखित युग्मों पर विचार कीजिए जिनके अधीन वे बने:', explanation_hi = 'केवल युग्म 1 और 3 सही हैं। तंजावुर का बृहदीश्वर मंदिर चोल राजा राजराज प्रथम ने बनवाया, और पट्टदकल का विरूपाक्ष मंदिर रानी लोकमहादेवी ने अपने पति, चालुक्य राजा विक्रमादित्य द्वितीय, की पल्लवों पर विजय की स्मृति में बनवाया। युग्म 2 नाम का जाल है: एलोरा का एकाश्म कैलास मंदिर राष्ट्रकूट राजा कृष्ण प्रथम के समय बना; पल्लव मंदिर कांचीपुरम का कैलासनाथ है। युग्म 4 गलत है: मोढेरा का सूर्य मंदिर परमारों नहीं, चौलुक्य (सोलंकी) वंश के भीम प्रथम के समय बना।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. बृहदीश्वर मंदिर, तंजावुर", "2. कैलास मंदिर, एलोरा", "3. विरूपाक्ष मंदिर, पट्टदकल", "4. सूर्य मंदिर, मोढेरा"], "list_2_hi": ["चोल", "पल्लव", "बादामी के चालुक्य", "परमार"]}'::jsonb where id = 'd21e616e-91b2-4c0e-9a7f-49a5e72a273e' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'शिव को ब्रह्मांडीय नर्तक के रूप में दर्शाने वाली प्रसिद्ध काँस्य ''नटराज'' प्रतिमा का सबसे गहरा संबंध किस राजवंश के संरक्षण से है?', explanation_hi = 'अग्नि के वलय के भीतर ब्रह्मांडीय तांडव करते शिव को दर्शाने वाली शास्त्रीय नटराज काँस्य प्रतिमा का सबसे गहरा संबंध चोल काल की काँस्य ढलाई से है, जो तमिलनाडु में चोल संरक्षण में खूब फली-फूली। पल्लव, बादामी के चालुक्य और राष्ट्रकूट, सभी दक्षिण/दक्कन के महत्त्वपूर्ण राजवंश हैं जिनका अपना विशिष्ट स्थापत्य और मूर्तिकला योगदान है, पर नटराज काँस्य परंपरा विशेष रूप से चोलों से जुड़ी है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "चोल", "b": "पल्लव", "c": "बादामी के चालुक्य", "d": "राष्ट्रकूट"}'::jsonb as hi) h) where id = '05391990-7fcb-445f-a3fb-76a146247ff8' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'जैन प्रतिमा-विज्ञान के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: तीर्थंकरों की पहचान लांछनों से होती है, और ऋषभनाथ का लांछन बैल है। कथन 2 तीर्थंकर बदल देता है: सर्प-फणों की छतरी पार्श्वनाथ की पहचान है, महावीर की नहीं। कथन 3 भी अदला-बदली है: महावीर का लांछन सिंह है, जबकि हाथी अजितनाथ का लांछन है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["जैन तीर्थंकरों की प्रतिमाएँ प्रायः विशिष्ट चिह्नों (लांछनों) से पहचानी जाती हैं; ऋषभनाथ का लांछन बैल है।", "महावीर को आम तौर पर सर्प-फणों की छतरी के नीचे दर्शाया जाता है।", "महावीर से जुड़ा लांछन हाथी है।"]}'::jsonb where id = 'f274f99b-9eda-402c-8c75-f65809f8777b' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'हिंदू प्रतिमा-विज्ञान में देवताओं और उनसे जुड़े वाहनों के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'युग्म 1, 3 और 4 सही हैं: कार्तिकेय (स्कंद) का वाहन मोर, अग्नि का मेढ़ा और शिव का बैल नंदी है। युग्म 2 दो नदी-देवियों की अदला-बदली है: मकर (मगरमच्छ जैसा जीव) गंगा का वाहन है, जबकि यमुना को कछुए (कूर्म) पर खड़ा दिखाया जाता है; यह जोड़ी गुप्त काल से मंदिरों के द्वारों पर मिलती है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. कार्तिकेय", "2. यमुना", "3. अग्नि", "4. शिव"], "list_2_hi": ["मोर", "मकर", "मेढ़ा", "नंदी (बैल)"]}'::jsonb where id = '6b20b725-9646-4d6a-ba62-53411dc998e5' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'कुतुबुद्दीन ऐबक और दिल्ली सल्तनत की स्थापना के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: मुहम्मद गोरी के पूर्व गुलाम (मामलूक) ऐबक ने गुलाम वंश की स्थापना की। कथन 2 गलत है: ऐबक ने केवल कुतुब मीनार का निर्माण शुरू किया; इसे इल्तुतमिश ने पूरा किया। कथन 3 गलत शासक का नाम देता है: सल्तनत को सुदृढ़ करने और इक्ता व्यवस्था को संगठित करने का श्रेय इल्तुतमिश को है; बलबन दशकों बाद (1266-87) शासक बना।', updated_at = now(), question_data = question_data || '{"statements_hi": ["मुहम्मद गोरी के पूर्व गुलाम (मामलूक) कुतुबुद्दीन ऐबक ने गुलाम (मामलूक) वंश की स्थापना की और उसे दिल्ली का पहला सुल्तान माना जाता है।", "ऐबक ने कुतुब मीनार का निर्माण शुरू किया, जो पूरी तरह उसी के शासनकाल में पूरा हुआ।", "ऐबक के ठीक बाद आए बलबन को दिल्ली सल्तनत को सुदृढ़ करने और इक्ता की प्रशासनिक व्यवस्था संगठित करने का श्रेय दिया जाता है।"]}'::jsonb where id = '9b6edd02-1266-470d-86a1-ad81d5a9d84c' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'विजयनगर साम्राज्य के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है: विजयनगर साम्राज्य तुलुव वंश के कृष्णदेवराय के समय अपने चरम पर पहुँचा। कथन 1 गलत तिथि देता है: साम्राज्य की स्थापना हरिहर और बुक्का ने 1336 में की थी, 1436 में नहीं। कथन 3 गलत विजेताओं का नाम देता है: तालीकोटा (1565) की पराजय दक्कन की सल्तनतों के एक संघ ने दी थी, मुगलों ने नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["विजयनगर साम्राज्य की स्थापना 1436 में हरिहर और बुक्का ने की, जिनका मार्गदर्शन परंपरा के अनुसार ऋषि विद्यारण्य ने किया।", "विजयनगर साम्राज्य तुलुव वंश के कृष्णदेवराय के समय अपने चरम पर पहुँचा।", "विजयनगर साम्राज्य को तालीकोटा के युद्ध (1565) में मुगल सम्राट अकबर के हाथों निर्णायक पराजय मिली।"]}'::jsonb where id = '9ca626de-9dcc-4598-88aa-bbbbbdc558da' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'बाबर और मुगल साम्राज्य की स्थापना के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं: बाबर ने पानीपत के पहले युद्ध (1526) में तोपखाने और तुलुगमा घेराबंदी की युक्ति से इब्राहीम लोदी को हराया। कथन 3 गलत है: बाबरनामा मूल रूप से बाबर की मातृभाषा चगताई तुर्की में लिखा गया था, और बाद में फ़ारसी में अनूदित हुआ।', updated_at = now(), question_data = question_data || '{"statements_hi": ["बाबर ने 1526 में पानीपत के पहले युद्ध में इब्राहीम लोदी को हराकर भारत में मुगल साम्राज्य की स्थापना की।", "बाबर ने इस युद्ध में तोपखाने और उस्मानी (ऑटोमन) शैली की ''तुलुगमा'' युक्ति का प्रभावी उपयोग किया।", "बाबर की आत्मकथा ''बाबरनामा'' मूल रूप से उसकी मातृभाषा फ़ारसी में लिखी गई थी।"]}'::jsonb where id = 'cf74862d-cea6-4583-beb0-3adc62d8b1e2' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'दिल्ली सल्तनत के प्रशासन की एक महत्त्वपूर्ण विशेषता ''इक्ता'' व्यवस्था का मुख्य अर्थ निम्नलिखित में से क्या था?', explanation_hi = 'इक्ता व्यवस्था में सरदारों और अधिकारियों को क्षेत्रीय इकाइयाँ सौंपी जाती थीं, जिनसे वे नकद वेतन के बदले, सैनिक और प्रशासनिक सेवा के बदले में, भू-राजस्व वसूलते थे। यह जज़िया (गैर-मुसलमानों पर कर) से अलग थी, किसानों के वंशानुगत भू-स्वामित्व की व्यवस्था नहीं थी, और मनसबदारी पद-व्यवस्था से भी अलग है, जो बाद की मुगल संस्था है।', updated_at = now() where id = 'f70e6048-ed4d-470f-ba52-839437106c17' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'मध्यकालीन भारत में सूफ़ी चिश्ती सिलसिले के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं: ख्वाजा मुईनुद्दीन चिश्ती ने अजमेर में इस सिलसिले की शुरुआत की, और सूफ़ी संत आम तौर पर ख़ानक़ाहों में रहते थे। कथन 3 गलत है: चिश्ती सिलसिला राज्य-संरक्षण और राजनीतिक सत्ता से निकटता से जान-बूझकर बचने के लिए जाना जाता था; यह सुहरावर्दी सिलसिले से बिल्कुल अलग था, जो ऐसा संरक्षण स्वीकार करता था।', updated_at = now(), question_data = question_data || '{"statements_hi": ["चिश्ती सिलसिले को भारत में ख्वाजा मुईनुद्दीन चिश्ती लाए, जो अजमेर में बस गए।", "सूफ़ी संत आम तौर पर ''ख़ानक़ाह'' नामक आश्रमों में रहते थे, जो आध्यात्मिक और सामाजिक गतिविधियों के केंद्र थे।", "चिश्ती सिलसिला अपनी साधना के केंद्रीय अंग के रूप में सल्तनत के शासकों से भूमि-अनुदान और राज्य-संरक्षण सक्रिय रूप से माँगता और स्वीकार करता था।"]}'::jsonb where id = '104d4e20-cdfc-4c3e-be0f-082b29f0ef55' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
